HEADS = {1: 'La expulsión de los moriscos', 4: 'Olivares, valido de Felipe IV', 8: 'Carlos II y la regencia'}


def extend(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(text='La paz de Felipe III\nLa Tregua de los Doce Años se firmó en Amberes el 9 de abril de 1609 entre España y las Provincias Unidas y duró hasta el 9 de abril de 1621: supuso un receso en la guerra de los Ochenta Años. Las Provincias Unidas habían perdido el apoyo de Francia e Inglaterra, con las que España había hecho la paz en 1598 y 1604, y estaban maltrechas económicamente; por su parte, España consideraba excesivo el coste en dinero y en vidas de mantener los tercios en Flandes. La fuente inglesa precisa que los españoles la veían como una medida temporal impuesta por el agotamiento financiero y que no reconocieron formalmente la independencia neerlandesa hasta Westfalia, en 1648.',
        quotes=[Q('es_tregua','fue un tratado de paz firmado en 1609 entre España(la monarquía hispánica) y las Provincias Unidas de los Países Bajos'), Q('es_tregua','el mantenimiento en Flandes de los tercios españoles suponía un gasto excesivo en dinero y en vidas humanas'), Q('en_tregua','agreed in Antwerp on 9 April 1609 and ended on 9 April 1621'), Q('en_tregua','the Spanish viewed it as a temporary measure forced on them by financial exhaustion and domestic issues')]))
    P.append(dict(text='¿Cansancio o estrategia? La llamada Pax Hispánica ha sido interpretada por muchos historiadores como un gesto de hastío por la guerra y de dificultad para reorganizar los ataques; la fuente sugiere que también pudo formar parte de una gran estrategia para recuperar la fuerza militar y económica y apartar a los adversarios. De hecho, Felipe III y sus consejeros pretendían que la tregua durase solo hasta que España pudiese reanudar la lucha. Esa ambigüedad explica que Felipe III haya sido juzgado más severamente que su hijo, aunque los resultados de ambos reinados fueran, según la misma fuente, difícilmente comparables a favor de este último.',
        quotes=[Q('es_felipe3','muchos historiadores han querido ver en la famosa Pax Hispánica un gesto de hastío por la guerra'), Q('es_felipe3','tanto Felipe III como sus consejeros pretendían que la tregua durase solo hasta que España pudiese reanudar las luchas'), Q('en_felipe3','After 1609, when it became evident that Spain was financially exhausted and Philip sought a truce with the Dutch, there followed a period of retrenchment')]))
    P.append(dict(text='La moneda de vellón\nLa economía bajo Felipe III tuvo varios problemas. El vellón, una aleación de plata y cobre, se adoptó a gran escala para las transacciones interiores, pero desde 1599 se manipuló quitando plata e incluso peso a la moneda para especular con el metal, de modo que el vellón no dejó de devaluarse frente al real de plata hasta la década de 1680. El jesuita Juan de Mariana denunció en De monetae mutatione (1609) esa reducción del contenido de plata, lo que hoy llamaríamos inflación. En 1607 se produjo una suspensión de pagos de la Hacienda, resuelta, como las de Felipe II, entregando juros a los banqueros acreedores. La fuente señala además que la inflación en la primera mitad del siglo XVII llegaría al 107 %.',
        quotes=[Q('es_felipe3','La adopción de la moneda de vellón (una aleación de plata y cobre) a gran escala para las transacciones en el interior del país'), Q('es_felipe3','El jesuita español Juan de Mariana denunció en su obra De monetae mutatione (1609)'), Q('es_felipe3','en 1607 se produciría una suspensión de pagos por parte de la Hacienda Real'), Q('en_felipe3','Father Juan de Mariana')]))
    P.append(dict(text='Hidalgos y señoríos. Otro rasgo de la época fue que los altos funcionarios, los burgueses y los labradores ricos acumulaban patrimonio como primer paso hacia la hidalguía; al haber tantos hidalgos se produjo una desvalorización de la simple hidalguía, y solo se consideraba realmente nobles a condes, duques y marqueses. Para dar el salto era necesario ser «señor de vasallos», por lo que Carlos I y Felipe II vendieron pueblos de monasterios y órdenes militares; Felipe IV vendió pueblos realengos. Con los Austrias se constituyeron unos doscientos señoríos, en parte para obtener un título. La venta de cargos y señoríos era una fuente de ingresos para la Corona y un factor de refeudalización.',
        quotes=[Q('es_felipe3','Los altos funcionarios, los burgueses y los labradores ricos acumulaban patrimonio como un primer paso hacia la hidalguía'), Q('es_felipe3','Para pasar de hidalgo o caballero a poseedor de uno de esos títulos era necesario ser "señor de vasallos"'), Q('en_decline','the rampant ennoblement of certain idle sectors of the population, the purchase of positions')]))
    P.append(dict(text='La Montaña Blanca\nEl emperador Fernando II pidió ayuda a sus parientes españoles para hacer frente a la rebelión de los protestantes alemanes. España, aliada de Austria y de Baviera, se enfrentó a los protestantes bohemios apoyados por el Palatinado; las tropas españolas mandadas por Ambrosio de Spínola en el Palatinado y las de la Liga al mando de Tilly vencieron en la batalla de la Montaña Blanca (1620). Fue la primera intervención española en la guerra de los Treinta Años, que se prolongaría hasta 1648, y mostró que la paz con los holandeses no significaba abandonar los frentes europeos, como ya hemos visto en la política de los «procónsules» de Felipe III.',
        quotes=[Q('es_felipe3','El emperador Fernando II de Habsburgo pidió ayuda a sus familiares españoles'), Q('es_felipe3','vencieron en la batalla de la Montaña Blanca en 1620'), Q('en_felipe3','the policies of Philip\'s \'proconsuls\'')]))
    P.append(dict(text='Olivares y la reforma moral\nCon Olivares, el rey Felipe IV, que subió al trono en 1621, quiso reformar la Monarquía. La fuente española describe una política interior con tres ejes: moral pública, restricciones a la inmigración y educación, a las que se sumó una política económica de crisis. No es una reforma abstracta: nace de la creencia de que el declive de la Monarquía tenía una causa moral y política y no solo económica. Como Lerma, Olivares es un caso de valido que gobierna en nombre del rey, pero a diferencia de él quiso un programa claro; sus detractores y sus defensores han tenido una larga historia de valoraciones, y la fuente señala que la historiografía lo juzga más favorablemente que a Lerma.',
        quotes=[Q('es_felipe4','Reinado con el valimiento del conde-duque de Olivares (1622-1643)'), Q('es_felipe4','La política económica de Felipe IV durante el valimiento del conde-duque de Olivares se basó en intentar paliar diversas crisis'), Q('es_felipe3','Felipe III ha sido juzgado mucho más severamente de lo que lo han sido su hijo, Felipe IV, y el valido de este, Olivares, más favorablemente que Lerma'), Q('en_felipe4','By the time of his death, the Spanish Empire had reached approximately 12.2 million square kilometres')]))
    P.append(dict(text='Vellón, quiebras y banqueros portugueses. En 1624 circulaban más de veinte millones de ducados en moneda de vellón, lo que produjo inflación en la década de 1620; el 7 de febrero de 1626 el rey ordenó prohibir las acuñaciones durante veinte años. El 31 de enero de 1627 decretó la suspensión de pagos y, con un decreto del 21 de enero de 1627, alentado por Olivares, permitió que banqueros portugueses financiasen a la Monarquía, con lo que los genoveses, que desde mediados del siglo XVI dominaban las finanzas del rey, perdieron influencia. Olivares recurrió a los portugueses para impedir que los genoveses pidieran intereses demasiado altos. El episodio muestra que la crisis fiscal no se resolvía con más impuestos sino con quién prestaba.',
        quotes=[Q('es_felipe4','en 1624 circulaban más de 20 millones de ducados de este tipo de moneda'), Q('es_felipe4','El 7 de febrero de 1626 el rey dio orden de prohibir las acuñaciones durante veinte años'), Q('es_felipe4','Con un decreto del 21 de enero de 1627, alentado por el conde-duque de Olivares, se permitió que banqueros portugueses financiasen a la monarquía hispánica'), Q('en_felipe4','Philip responded to the perceived weakness of France during the Fronde rebellions')]))
    P.append(dict(text='La sal, los millones y la rebelión vasca. En 1631 se sustituyó el impuesto de los millones por un estanco de la sal, que Castilla la Nueva y Andalucía agradecieron pero que perjudicó al norte, con gran demanda de sal para la ganadería y las conservas de pescado. El clero se quejó, las Juntas Generales vascas lo rechazaron unánimemente y se produjeron disturbios: el 22 de octubre de 1632 los rebeldes asaltaron en Bilbao la casa del alcalde. Con el impuesto de la sal se ingresó menos que con los millones, y en 1632 las Cortes de Castilla decidieron restablecer los millones. Guipúzcoa consiguió el fin del estanco en 1634, y Vizcaya, dos meses después.',
        quotes=[Q('es_felipe4','En 1631 se sustituyó el impuesto de los millones por un estanco de la sal'), Q('es_felipe4','La negativa de las Juntas Generales vascas al estanco de la sal fue unánime'), Q('es_felipe4','Con el impuesto de la sal se terminó por ingresar menos que con los millones'), Q('en_felipe4','Philip and Olivares attempted to address the perceived')]))
    P.append(dict(text='1640-1643: plata escasa y deflación. La plata que llegó en galeones en 1639 era incapaz de hacer frente a los gastos y en 1640 hubo gran escasez; la Corona impuso en noviembre un «donativo general por fuegos» que generó gran descontento. Entre 1641 y 1642 se produjo una exagerada inflación de los precios en vellón y el 15 de septiembre de 1642 el gobierno decretó una deflación gigantesca, que provocó una pobreza inmensa en Castilla. La pobreza redujo la recaudación y dificultó los asientos con los banqueros; las peticiones de dinero tuvieron que reducirse de quince millones de ducados a seis y luego a cuatro. Es el trasfondo económico de la caída de Olivares en 1643.',
        quotes=[Q('es_felipe4','La plata que llegó en galeones en 1639 era incapaz de hacer frente a los enormes gastos'), Q('es_felipe4','el 15 de septiembre de 1642 el gobierno decretó una deflación gigantesca'), Q('es_felipe4','Esto provocó una pobreza inmensa en Castilla'), Q('en_felipe4','The Peace of Westphalia, delivered by Olivares\' replacement Luis de Haro')]))
    P.append(dict(text='Hambre y revueltas, 1647-1652\nDomínguez Ortiz llamó «alteraciones andaluzas» a una serie de levantamientos entre 1647 y 1652 en Sevilla, Córdoba, Málaga, Granada y numerosos pueblos, causados sobre todo por los altos precios de los alimentos, en especial del pan. En 1647 estallaron también rebeliones antifiscales en Nápoles, encabezada por el pescador Masaniello el 7 de junio ({{fig:masaniello}}), y en Sicilia. En Nápoles los rebeldes pedían abolir impuestos como el de la fruta y restaurar los privilegios de la ciudad, y la rebelión tomó tintes antiespañoles hasta que Juan José de Austria la sofocó en 1648. En Palermo, el virrey aceptó cuarenta y nueve capítulos que, sin embargo, estaban abolidos hacia 1650.',
        quotes=[Q('es_felipe4','definió en 1973 como "alteraciones andaluzas" a una serie de levantamientos que tuvieron lugar entre 1647 y 1652'), Q('es_felipe4','El 7 de junio de 1647 el vendedor de pescado Tomas Aniello (Masaniello) encabezó una rebelión en Nápoles'), Q('es_felipe4','todas las reformas incluidas en los cuarenta y nueve capítulos habían quedado abolidas para 1650'), Q('en_felipe4','The Peace of Westphalia')]))
    P.append(dict(text='Una monarquía desbordada. Los años de Luis de Haro (1643-1661) completan el cuadro: rebeliones andaluzas, napolitanas y sicilianas, la conspiración del duque de Híjar de 1648 para nombrar rey de Aragón con ayuda de Francia, la guerra con Francia y el fracaso en Portugal. La fuente inglesa subraya que de Haro es considerado por los historiadores la «encarnación de la mediocridad» y que la contrarreforma del sistema de comités de Olivares se detuvo; el gobierno personal volvió al favorito. La imagen de decadencia política se asienta en estos años, aunque algunos territorios, como Castilla, vivieron la crisis de modo distinto de la periferia.',
        quotes=[Q('es_felipe4','En 1648 se conoció'), Q('en_felipe4','De Haro has not been highly regarded by historians'), Q('en_felipe4','the counter-reform of the committee system halted')]))
    P.append(dict(text='Carlos II: la regencia\nCarlos II ({{fig:carlos2}}) fue proclamado rey en 1665, a los tres años, con una mala salud que llevó a sobreprotegerlo y a descuidar su educación para el gobierno. Durante la regencia de su madre, Mariana de Austria, gobernó el valido Juan Everardo Nithard, su confesor jesuita, que logró acabar con las guerras con Francia y Portugal mediante los tratados de 1668; don Juan José de Austria, hijo natural de Felipe IV, forzó su destitución en 1669. La reina lo sustituyó por Fernando de Valenzuela, de la pequeña hidalguía, y en 1677 don Juan José marchó sobre Madrid con apoyo de la nobleza y se convirtió en el nuevo valido, hasta su muerte en 1679.',
        quotes=[Q('es_carlos2','Carlos II fue proclamado rey en 1665, a los tres años'), Q('en_carlos2','ruled through a "valido", the first being her personal confessor and fellow Austrian, Juan Everardo Nithard'), Q('en_carlos2','in February 1669 Don Juan forced Mariana to dismiss Nithard'), Q('es_carlos2','Juan José de Austria marchó sobre Madrid y tomó el poder apoyándose en la nobleza')]))
