def figures(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    from figs import timeline
    pop = r"""
\draw[->, thick] (0,0) -- (0,4.4); \draw[->, thick] (0,0) -- (9.2,0);
\node[font=\scriptsize, rotate=90] at (-0.8,2.0) {millones de habitantes};
\foreach \y/\l in {0/0,0.5/1,1.0/2,1.5/3,2.0/4,2.5/5,3.0/6,3.5/7,4.0/8} { \draw (-0.08,\y) -- (0.08,\y); \node[font=\scriptsize, anchor=east] at (-0.1,\y) {\l}; }
\fill[blue!35] (0.6,0) rectangle (1.6,3.25); \fill[red!45] (1.8,0) rectangle (2.8,2.45);
\fill[blue!35] (4.8,0) rectangle (5.8,4.25); \fill[red!45] (6.0,0) rectangle (7.0,3.3);
\node[font=\tiny\bfseries] at (1.1,3.45) {6,5}; \node[font=\tiny\bfseries] at (2.3,2.65) {$<$5};
\node[font=\tiny\bfseries] at (5.3,4.45) {8,5}; \node[font=\tiny\bfseries] at (6.5,3.5) {6,6};
\node[font=\scriptsize] at (1.7,-0.5) {Castilla}; \node[font=\scriptsize] at (5.9,-0.5) {España};
\fill[blue!35] (7.8,3.9) rectangle (8.1,4.1); \node[font=\scriptsize, anchor=west] at (8.15,4.0) {1600};
\fill[red!45] (7.8,3.4) rectangle (8.1,3.6); \node[font=\scriptsize, anchor=west] at (8.15,3.5) {1680};
"""
    return [
        dict(kind='tikz', key='poblacion-1600-1680', source=pop,
             caption='Población de Castilla y de España en 1600 y en 1680, según la fuente (millones de habitantes). La cifra de Castilla en 1680 es «menos de cinco».',
             quotes=[Q('en_carlos2','the population dropped from 6.5 million in 1600 to fewer than 5 million in 1680'), Q('en_carlos2','whilst figures for Spain as a whole were 8.5 to 6.6 million')]),
        dict(kind='tikz', key='siglo17-cronologia', source=timeline([('1607','Suspensión de pagos'),('1609','Tregua y bando morisco'),('1620','Montaña Blanca'),('1627','Quiebra y banqueros portugueses'),('1642','Deflación'),('1647','Nápoles y Andalucía'),('1659','Pirineos'),('1686','Estabiliza la moneda')], width=14.5, label_width=2.3),
             caption='Cronología económica y política del siglo XVII hispano, 1607-1686.',
             quotes=[Q('es_felipe3','en 1607 se produciría una suspensión de pagos por parte de la Hacienda Real'), Q('es_tregua','fue un tratado de paz firmado en 1609'), Q('es_felipe3','vencieron en la batalla de la Montaña Blanca en 1620'), Q('es_felipe4','Con un decreto del 21 de enero de 1627'), Q('es_felipe4','el 15 de septiembre de 1642 el gobierno decretó una deflación gigantesca'), Q('en_carlos2','in 1686 the coinage was readjusted to a more favourable rate')]),
        dict(kind='image', key='carlos2', commons='File:Retrato de Carlos II, rey de España - Juan Carreño de Miranda.jpg',
             caption='Carlos II, retrato de Juan Carreño de Miranda.',
             quotes=[Q('es_carlos2','Carlos II fue proclamado rey en 1665, a los tres años'), Q('en_carlos2','in February 1669 Don Juan forced Mariana to dismiss Nithard')]),
        dict(kind='image', key='masaniello', commons='File:Michelangelo Cerquozzi and Viviano Codazzi - The revolt of Masaniello.jpg',
             caption='La revuelta de Masaniello en Nápoles (1647), según Cerquozzi y Codazzi.',
             quotes=[Q('es_felipe4','El 7 de junio de 1647 el vendedor de pescado Tomas Aniello (Masaniello) encabezó una rebelión en Nápoles'), Q('es_felipe4','Los rebeldes pedían la abolición de impuestos como el de la fruta')]),
    ]


